/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: at, redirect, image, solid, recordingGate, client, fetchFront, failure
 *   Constants: guard, path, stored
 * Tests
 *   - only a thumbnail address on the fixed artwork hosts is rewritten to the size asked for, and only the same path on another artwork host is followed
 *   - the artwork is fetched through the itunes gate with the product-only User-Agent and three headers, following at most three allowlisted hops
 *   - a private, loopback or link-local DNS answer is refused before anything is sent
 *   - oversized, larger than asked, pixel-bomb, undecodable or mistyped artwork is refused, 404 is no artwork, 403/429/503 are rate limited, and bytes are never cached
 * @end-catalog */

/**
 * iTunes artwork of an iTunes-only candidate (itunesArtworkClient.ts) without any network: the stored 100-pixel address rewritten
 * only on the fixed artwork hosts, the redirect allowlist (another artwork host, same path, no query), SSRF refusals, the `itunes`
 * gate with the product-only User-Agent and three headers, byte, pixel and decode bounds, 404 as no artwork and bytes never cached.
 * Every image is generated here; every address is synthetic.
 */
import assert from 'node:assert/strict';
import type { LookupAddress } from 'node:dns';
import { after, test } from 'node:test';
import sharp from 'sharp';
import type { PinnedHttpsTransport } from '../../src/administration/adminPinnedHttps';
import type { CoverArtFrontSize } from '../../src/administration/lookup/coverArtClient';
import { createItunesArtworkClient, itunesArtworkDestination, itunesArtworkUrl } from '../../src/administration/lookup/itunesArtworkClient';
import { MetadataLookupInputError, MetadataLookupSourceError, type LookupGateMode, type MetadataLookupSource } from '../../src/administration/lookup/lookupContract';
import type { MetadataLookupRateGate } from '../../src/administration/lookup/lookupRateGate';
import { createLookupResponseCache } from '../../src/administration/lookup/lookupResponseCache';
import type { LookupClientDependencies } from '../../src/administration/lookup/lookupSourceRequest';
import { availableLookupConfiguration, fixtureAddress, fixtureTransport, type LookupExchange } from '../support/metadataLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const path = '/image/thumb/Music126/v4/53/0f/80/530f802b-6623-b4ae-213a-859449bf7326/ANTCD-46555.jpg/';
const stored = `https://is1-ssl.mzstatic.com${path}100x100bb.jpg`;
const at = (size: number, host = 'is1-ssl.mzstatic.com') => `https://${host}${path}${size}x${size}bb.jpg`;
const redirect = (url: string, location: string, status = 302): LookupExchange => ({ url, status, headers: { location } });
const image = (url: string, bytes: Buffer, contentType = 'image/jpeg', headers: Record<string, string | null> = {}): LookupExchange =>
    ({ url, status: 200, headers: { 'content-type': contentType, ...headers }, bodyBase64: bytes.toString('base64') });
const solid = (width: number, height: number) => sharp({ create: { width, height, channels: 3, background: { r: 153, g: 102, b: 51 } } });
const recordingGate = () => {
    const record = { sources: [] as MetadataLookupSource[], modes: [] as LookupGateMode[], sends: 0 };
    const gate: MetadataLookupRateGate = { acquire: async (source, mode) => { record.sources.push(source); record.modes.push(mode); return { sent: () => { record.sends++; }, release: async () => undefined }; } };
    return { gate, record };
};
const client = (transport: PinnedHttpsTransport, overrides: Partial<LookupClientDependencies> = {}) => {
    const { gate, record } = recordingGate(), cache = createLookupResponseCache(), cached: string[] = [], scheduled: string[] = [];
    const artwork = createItunesArtworkClient({ gate, transport, configuration: availableLookupConfiguration, sleep: async () => undefined,
        cache: { get: key => cache.get(key), set: (key, value, bytes) => { cached.push(key); cache.set(key, value, bytes); }, clear: () => cache.clear() },
        schedule: (key, _signal, operation) => { scheduled.push(key); return operation(); }, ...overrides });
    return { artwork, record, cached, scheduled };
};
const fetchFront = (current: ReturnType<typeof client>, size: CoverArtFrontSize = 1200, address = stored, mode: LookupGateMode = 'wait') =>
    current.artwork.front(address, size, { mode, signal: new AbortController().signal, clientKey: '0000000000000000000000a1' });
const failure = (kind: string) => (error: unknown) => {
    assert.ok(error instanceof MetadataLookupSourceError, String(error));
    assert.equal(error.source, 'itunes'); assert.equal(error.failure, kind);
    return true;
};

test('only a thumbnail address on the fixed artwork hosts is rewritten to the size asked for, and only the same path on another artwork host is followed', () => {
    assert.equal(itunesArtworkUrl(stored, 1200)!.href, at(1200));
    assert.equal(itunesArtworkUrl(stored.replace('100x100bb.jpg', '60x60bb.png'), 500)!.href, at(500));
    for (const value of [null, 7, '', 'https://example.test/image/thumb/a/100x100bb.jpg', stored.replace('https:', 'http:'), `${stored}?x=1`, `${stored}#x`, stored.replace('is1-ssl', 'is6-ssl'),
        stored.replace('mzstatic.com', 'mzstatic.com:8443'), stored.replace('/image/thumb/', '/other/'), stored.replace('100x100bb.jpg', 'source.jpg'), 'https://is1-ssl.mzstatic.com/100x100bb.jpg',
        'https://user:secret@is1-ssl.mzstatic.com/image/thumb/a/100x100bb.jpg', 'https://93.184.216.34/image/thumb/a/100x100bb.jpg']) {
        assert.equal(itunesArtworkUrl(value, 1200), null, String(value));
    }
    assert.equal(itunesArtworkUrl(stored, 250 as CoverArtFrontSize), null);
    const allow = itunesArtworkDestination(new URL(at(1200))), allowed = (url: string, hop: number) => allow(new URL(url), hop)?.href ?? null;
    assert.equal(allowed(at(1200), 0), at(1200));
    assert.equal(allowed(at(1200, 'is3-ssl.mzstatic.com'), 0), null, 'hop 0 is only the rewritten address');
    for (const host of ['is1-ssl.mzstatic.com', 'is5-ssl.mzstatic.com']) assert.equal(allowed(at(1200, host), 2), at(1200, host));
    for (const url of [at(500, 'is2-ssl.mzstatic.com'), `${at(1200, 'is2-ssl.mzstatic.com')}?x=1`, at(1200, 'is6-ssl.mzstatic.com'), at(1200, 'evil.example'), at(1200).replace('https:', 'http:'),
        at(1200).replace('mzstatic.com', 'mzstatic.com:8443'), 'https://93.184.216.34/image/thumb/x.jpg', at(1200, 'is2-ssl.mzstatic.com.evil.example')]) assert.equal(allowed(url, 1), null, url);
});

test('the artwork is fetched through the itunes gate with the product-only User-Agent and three headers, following at most three allowlisted hops', async () => {
    const bytes = await solid(64, 48).jpeg().toBuffer();
    const chain = [redirect(at(1200), at(1200, 'is2-ssl.mzstatic.com'), 307), redirect(at(1200, 'is2-ssl.mzstatic.com'), at(1200, 'is3-ssl.mzstatic.com')), image(at(1200, 'is3-ssl.mzstatic.com'), bytes)];
    const fake = fixtureTransport(chain), current = client(fake.transport);
    const artwork = await fetchFront(current);
    assert.deepEqual([artwork?.contentType, artwork?.bytes.equals(bytes)], ['image/jpeg', true]);
    assert.deepEqual(fake.requests.map(request => request.url), chain.map(exchange => exchange.url));
    for (const request of fake.requests) assert.deepEqual({ ...request.headers }, { Accept: 'image/jpeg, image/png, image/webp', 'Accept-Encoding': 'identity', 'User-Agent': 'Finitude/1.0' });
    assert.ok(fake.requests.every(request => !JSON.stringify(request.headers).includes('lookup-operator')), 'no contact reaches Apple');
    assert.deepEqual([current.record.sources, current.record.modes, current.record.sends, current.scheduled, current.cached], [['itunes'], ['wait'], 3, ['0000000000000000000000a1'], []]);
    // A fourth redirect, another path or a query is refused unfollowed.
    const long = fixtureTransport([redirect(at(1200), at(1200, 'is2-ssl.mzstatic.com')), redirect(at(1200, 'is2-ssl.mzstatic.com'), at(1200, 'is3-ssl.mzstatic.com')),
        redirect(at(1200, 'is3-ssl.mzstatic.com'), at(1200, 'is4-ssl.mzstatic.com')), redirect(at(1200, 'is4-ssl.mzstatic.com'), at(1200, 'is5-ssl.mzstatic.com'))]);
    await assert.rejects(fetchFront(client(long.transport)), failure('unavailable'));
    assert.equal(long.requests.length, 4);
    for (const location of [at(500, 'is2-ssl.mzstatic.com'), `${at(1200, 'is2-ssl.mzstatic.com')}?q=1`, 'https://example.org/x.jpg']) {
        const refused = fixtureTransport([redirect(at(1200), location, 307)]);
        await assert.rejects(fetchFront(client(refused.transport)), failure('unavailable'), location);
        assert.equal(refused.requests.length, 1);
    }
    // An address that cannot be rewritten is refused before the gate.
    const nothing = fixtureTransport([]), refusedInput = client(nothing.transport);
    await assert.rejects(fetchFront(refusedInput, 1200, 'https://example.test/image/thumb/a/100x100bb.jpg'), MetadataLookupInputError);
    assert.deepEqual([nothing.lookups, refusedInput.record.sources], [[], []]);
});

test('a private, loopback or link-local DNS answer is refused before anything is sent', async () => {
    for (const answers of [[{ address: '10.0.0.1', family: 4 }], [{ address: '127.0.0.1', family: 4 }], [{ address: '169.254.169.254', family: 4 }], [{ address: '::1', family: 6 }],
        [fixtureAddress, { address: '192.168.1.1', family: 4 }]] as LookupAddress[][]) {
        const fake = fixtureTransport([image(at(1200), await solid(8, 8).jpeg().toBuffer())]);
        await assert.rejects(fetchFront(client({ ...fake.transport, lookup: async () => answers })), failure('unavailable'), JSON.stringify(answers));
        assert.deepEqual(fake.requests, []);
    }
});

test('oversized, larger than asked, pixel-bomb, undecodable or mistyped artwork is refused, 404 is no artwork, 403/429/503 are rate limited, and bytes are never cached', async () => {
    const bytes = await solid(64, 48).jpeg().toBuffer(), bomb = await solid(5000, 4000).png({ compressionLevel: 9 }).toBuffer();
    const cases: [LookupExchange, string, CoverArtFrontSize?][] = [
        [image(at(1200), Buffer.alloc(16), 'image/jpeg', { 'content-length': String(4 * 1024 * 1024 + 1) }), 'unavailable'],
        [image(at(1200), bomb, 'image/png'), 'invalidResponse'],
        [image(at(1200), await solid(1201, 10).jpeg().toBuffer()), 'invalidResponse'],
        [image(at(500), await solid(600, 600).jpeg().toBuffer()), 'invalidResponse', 500],
        [image(at(1200), bytes.subarray(0, bytes.length - 40)), 'invalidResponse'],
        [image(at(1200), bytes, 'image/gif'), 'invalidResponse'],
        [image(at(1200), bytes, 'image/jpeg', { 'content-encoding': 'gzip' }), 'invalidResponse']];
    for (const [exchange, kind, size] of cases) {
        const current = client(fixtureTransport([exchange]).transport);
        await assert.rejects(fetchFront(current, size ?? 1200), failure(kind), `${exchange.headers['content-type']} ${kind}`);
        assert.deepEqual(current.cached, []);
    }
    const missing = client(fixtureTransport([{ url: at(1200), status: 404, headers: { 'content-type': 'text/html' } }]).transport);
    assert.equal(await fetchFront(missing), null);
    for (const status of [403, 429, 503]) {
        const busy = client(fixtureTransport([{ url: at(1200), status, headers: { 'content-type': 'text/html' } }]).transport);
        await assert.rejects(fetchFront(busy, 1200, stored, 'busy'), failure('rateLimited'), String(status));
    }
    const twice = fixtureTransport([image(at(500), bytes), image(at(500), bytes)]), repeated = client(twice.transport);
    await fetchFront(repeated, 500); await fetchFront(repeated, 500);
    assert.deepEqual([twice.requests.length, repeated.cached], [2, []]);
    const fake = fixtureTransport([]), unconfigured = client(fake.transport, { configuration: () => ({ available: false, reason: 'contactMissing' }) });
    await assert.rejects(fetchFront(unconfigured), failure('notConfigured'));
    assert.deepEqual(fake.requests, []);
});
